"use client";

import "./separator.css";

import type React from "react";

import { Separator as BaseSeparator } from "@base-ui/react/separator";
import { cn } from "tailwind-variants";

import { SeparatorContext, useSeparatorContext } from "./separator.context";
import { separatorVariants, type SeparatorVariants } from "./separator.variants";

export type SeparatorProps = SeparatorVariants & React.ComponentProps<typeof BaseSeparator>;

export const SeparatorRoot = ({
  className,
  orientation = "horizontal",
  ...props
}: SeparatorProps) => {
  const slots = separatorVariants({ orientation });

  return (
    <SeparatorContext.Provider value={{ slots }}>
      <BaseSeparator className={cn(slots.root(), className)} orientation={orientation} {...props} />
    </SeparatorContext.Provider>
  );
};

export const Separator = SeparatorRoot;

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const separatorVariants = tv({
  slots: {
    root: "separator",
  },
  variants: {
    orientation: {
      horizontal: {
        root: "separator--horizontal",
      },
      vertical: {
        root: "separator--vertical",
      },
    },
  },
  defaultVariants: {
    orientation: "horizontal",
  },
});

export type SeparatorVariants = VariantProps<typeof separatorVariants>;

"use client";

import { createContext, useContext } from "react";

import { separatorVariants } from "./separator.variants";

export type SeparatorContext = {
  slots: ReturnType<typeof separatorVariants>;
};

export const SeparatorContext = createContext<SeparatorContext | null>(null);

export const useSeparatorContext = () => {
  const context = useContext(SeparatorContext);
  return context ?? { slots: separatorVariants() };
};

.separator {
  @apply shrink-0 bg-border;
}

.separator--horizontal {
  @apply h-px w-full;
}

.separator--vertical {
  @apply h-full w-px;
}

import { SeparatorRoot } from "./separator";

export const Separator = {
  Root: SeparatorRoot,
};

export { SeparatorRoot, SeparatorRoot as SeparatorComponent };
export { Separator as SeparatorAlias } from "./separator";

export type { SeparatorProps } from "./separator";
export { SeparatorContext, useSeparatorContext } from "./separator.context";
export { type SeparatorVariants, separatorVariants } from "./separator.variants";
